'use strict';
const $=id=>document.getElementById(id);
const safeRead=()=>{try{const v=JSON.parse(localStorage.getItem('river-ride-completed')||'[]');return Array.isArray(v)?v.filter(n=>Number.isInteger(n)&&n>=0&&n<5):[];}catch{return [];}};
let completed=new Set(safeRead());
const tripDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Prague',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateDay=()=>days.findIndex(d=>d.date===tripDate());
const hashDay=()=>{const m=location.hash.match(/^#day-([1-5])$/);return m?Number(m[1])-1:null;};
let selected=hashDay()??Math.max(0,dateDay()),map,layer,markers=[],mapFailed=false;
const dateLabel=date=>new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/Prague'}).format(new Date(date+'T12:00:00Z'));
const sourceFor=key=>'https://commons.wikimedia.org/wiki/File:'+encodeURIComponent(photos[key].file);
const locationFor=p=>'https://www.openstreetmap.org/?mlat='+p.coords[0]+'&mlon='+p.coords[1]+'#map=16/'+p.coords.join('/');
function notify(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').classList.remove('show'),3500);}
function showDialog(html){$('detail-content').innerHTML=html;$('detail').showModal();}
function photoCredit(key){const p=photos[key];return `<a href="${sourceFor(key)}" target="_blank" rel="noopener">${p.author} / Wikimedia Commons</a> · <a href="https://creativecommons.org/licenses/${p.license}/" target="_blank" rel="noopener">CC ${p.license.replace('/',' ').toUpperCase()}</a> · display crop`;}
function showPlace(id){const p=places[id];showDialog(`<img class="detail-photo" src="assets/${p.photo}.jpg" alt="${p.name}"><div class="detail-body"><span class="eyebrow">${p.category}</span><h2>${p.name}</h2><p>${p.description}</p><p>${p.detail}</p><p><strong>Suggested visit:</strong> ${p.time}<br><strong>Access:</strong> ${p.access}</p><p><a class="primary" href="${locationFor(p)}" target="_blank" rel="noopener">Open location</a> &nbsp; <a href="${p.url}" target="_blank" rel="noopener">Visitor information</a></p><p style="font-size:11px">${photoCredit(p.photo)}</p></div>`);}
function drawMap(){if(!map)return;layer.clearLayers();markers=[];const d=days[selected];L.polyline(d.line,{color:'#24795d',weight:4,opacity:.8,dashArray:'7 8'}).addTo(layer);for(const [i,id] of d.stops.entries()){const p=places[id];const marker=L.marker(p.coords,{icon:L.divIcon({className:'place-marker',html:String(i+1),iconSize:[32,32],iconAnchor:[16,16]}),title:p.name,alt:p.name}).addTo(layer);const popup=document.createElement('div');const b=document.createElement('strong');b.textContent=p.name;popup.append(b,document.createElement('br'));const detail=document.createElement('button');detail.textContent='Explore this stop';detail.addEventListener('click',()=>showPlace(id));popup.append(detail);marker.bindPopup(popup);markers.push(marker);}fitMap();}
function fitMap(){if(map){const d=days[selected];map.fitBounds(L.latLngBounds([...d.line,...d.stops.map(id=>places[id].coords)]),{padding:[28,28],maxZoom:12});}}
function focusPlace(index){if(!map){showPlace(days[selected].stops[index]);return;}const p=places[days[selected].stops[index]];map.setView(p.coords,14);markers[index].openPopup();$('map-section').scrollIntoView({behavior:'smooth',block:'center'});}
function updateProgress(){const total=[...completed].reduce((sum,i)=>sum+days[i].km,0);$('completion-count').textContent=`${completed.size} of 5 rides completed`;$('progress-label').textContent=`${total} / 225 km completed`;$('progress-bar').style.width=completed.size*20+'%';$('complete').textContent=completed.has(selected)?'✓ Ride completed · undo':'Mark ride as completed';$('complete').setAttribute('aria-pressed',String(completed.has(selected)));}
function render(){const d=days[selected];$('day-tabs').innerHTML=days.map((day,i)=>`<button class="day-tab ${i===selected?'active':''}" data-day="${i}" aria-pressed="${i===selected}"><span class="tab-top"><span>DAY ${i+1} ${completed.has(i)?'✓':''}</span><span>${12+i} SEP</span></span><strong>${day.from} – ${day.to}</strong><small>~${day.km} km · ${day.terrain}</small></button>`).join('');$('day-label').textContent=`DAY ${selected+1} / 5`;$('day-date').textContent=dateLabel(d.date);$('day-title').textContent=d.from+' to '+d.to;$('day-description').textContent=d.description;$('day-km').textContent='~'+d.km+' km';$('day-time').textContent=d.time;$('day-terrain').textContent=d.terrain;$('stage-line').innerHTML=`<span>${d.from}</span><i></i><span class="via">${d.via}</span><i></i><span>${d.to}</span>`;$('note-title').textContent=d.note;$('day-tip').textContent=d.tip;$('stops-count').textContent=d.stops.length+' highlights';$('stop-list').innerHTML=d.stops.map((id,i)=>`<button class="stop-row" data-focus="${i}"><span class="stop-number">${i+1}</span><span><strong>${places[id].name}</strong><small>${places[id].time} · ${places[id].access}</small></span></button>`).join('');$('attractions').innerHTML=d.stops.map(id=>{const p=places[id];return `<article class="attraction"><button class="attraction-image" data-place="${id}" aria-label="Explore ${p.name}"><img src="assets/${p.photo}.jpg" alt="${p.name}" loading="lazy"></button><div class="attraction-body"><span class="category">${p.category}</span><h3>${p.name}</h3><p>${p.description}</p><div class="card-links"><button class="text-button" data-place="${id}">Explore stop</button><a href="${locationFor(p)}" target="_blank" rel="noopener">Location</a></div></div></article>`;}).join('');updateProgress();drawMap();}
function selectDay(index,hash=true){selected=index;render();if(hash)history.replaceState(null,'','#day-'+(index+1));}
document.addEventListener('click',e=>{const day=e.target.closest('[data-day]'),place=e.target.closest('[data-place]'),focus=e.target.closest('[data-focus]');if(day)selectDay(Number(day.dataset.day));if(place)showPlace(place.dataset.place);if(focus)focusPlace(Number(focus.dataset.focus));});
$('complete').addEventListener('click',()=>{if(completed.has(selected))completed.delete(selected);else completed.add(selected);try{localStorage.setItem('river-ride-completed',JSON.stringify([...completed]));}catch{notify('Progress cannot be saved in this browser.');}render();});
$('today').addEventListener('click',()=>{const i=dateDay();selectDay(Math.max(0,i));if(i<0)notify(tripDate()<days[0].date?'The adventure starts on 12 September 2027. Showing Day 1.':'The trip has finished. Browse all five days.');$('dashboard').scrollIntoView({behavior:'smooth'});});
$('map-reset').addEventListener('click',fitMap);
$('detail').querySelector('.close').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close();}});
$('share').addEventListener('click',async()=>{const url=new URL(location.href);url.hash='day-'+(selected+1);try{if(navigator.share)await navigator.share({title:'River Ride · Prague to Dresden',text:'Our five-day cycling adventure, 12–16 September 2027',url:url.href});else{await navigator.clipboard.writeText(url.href);notify('Trip link copied. Share it with the group!');}}catch(e){if(e.name!=='AbortError')showDialog(`<div class="detail-body"><h2>Share our adventure</h2><p>Copy this link and send it to the group:</p><input aria-label="Trip link" readonly style="width:100%;padding:12px" value="${url.href.replaceAll('&','&amp;').replaceAll('"','&quot;')}"></div>`);}});
$('credits').addEventListener('click',()=>showDialog(`<div class="detail-body"><h2>Behind the photographs</h2><p>Original photographs from Wikimedia Commons. Images are displayed with a crop; each retains its original licence.</p>${Object.keys(photos).map(key=>`<div class="credit-row"><strong>${photos[key].file}</strong><br>${photoCredit(key)}</div>`).join('')}<p>Map data © OpenStreetMap contributors. Map tiles © OpenStreetMap contributors. Mapping library: Leaflet.</p></div>`));
$('trip-info').addEventListener('click',()=>showDialog(`<div class="detail-body"><h2>Our trip, at a glance</h2><p><strong>12–16 September 2027 · 5 riding days · approximately 225 km</strong></p><p>A fixed suggested itinerary for our group. Overnight towns are planning assumptions and have not been matched to booked hotels.</p><ul><li>Day 1: Prague – Mělník, ~55 km</li><li>Day 2: Mělník – Litoměřice, ~50 km</li><li>Day 3: Litoměřice – Děčín, ~50 km</li><li>Day 4: Děčín – Bad Schandau, ~25 km</li><li>Day 5: Bad Schandau – Dresden, ~45 km</li></ul><p>*Riding times assume a relaxed moving pace of roughly 14–18 km/h and exclude sightseeing, meals, ferries and detours. Distances vary with the chosen riverbank and actual start and finish points.</p><p>The map connects stage waypoints schematically. It is for exploring attractions; use the tour operator’s confirmed GPX for cycling navigation. Some sections use shared roads, and local closures or ferries may change the route. Bastei, Střekov and Terezín are optional excursions.</p><p>During the trip, the app opens on the current riding day using Prague local time. Before the trip, it opens on Day 1. A shared day link opens that day. Completion is personal to this browser.</p><h3>Route references</h3><p><a href="https://www.elbe-cycle-route.com/" target="_blank" rel="noopener">Official Elbe Cycle Route: maps & visitor updates</a><br><a href="https://www.rueckenwind.de/en/destinations/biketours-germany/cycle-tour-prague-dresden" target="_blank" rel="noopener">Prague–Dresden itinerary reference</a></p><p>Content prepared in November 2026. Check opening times and route conditions closer to September 2027.</p></div>`));
window.addEventListener('hashchange',()=>{const i=hashDay();if(i!==null)selectDay(i,false);});
try{if(typeof L==='undefined')throw Error('Leaflet unavailable');map=L.map('map',{scrollWheelZoom:false});layer=L.layerGroup().addTo(map);let errors=0;L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,referrerPolicy:'strict-origin-when-cross-origin',attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).on('tileerror',()=>{if(++errors>3){$('map-fallback').hidden=false;$('map-fallback').textContent='Map tiles could not load. Attraction markers and location links are still available.';}}).addTo(map);}catch{mapFailed=true;$('map-fallback').hidden=false;$('map').style.display='none';}
render();
